package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"regexp"
	"strings"

	"golang.org/x/tools/go/analysis"
)

// Config holds the user-tunable settings of the linter.
type Config struct {
	IgnoreSigs             []string
	ExtraIgnoreSigs        []string
	IgnoreSigRegexps       []string
	IgnorePackageGlobs     []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors   bool
}

// defaultIgnoreSigs is the set of signature fragments ignored when the user
// does not provide their own list.
var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

const (
	msgInterface = "error returned from interface method should be wrapped: sig: %s"
	msgExternal  = "error returned from external package is unwrapped: sig: %s"
	msgInternal  = "package-internal error should be wrapped: sig: %s"
)

func newAnalyzer(cfg Config) *analysis.Analyzer {
	return &analysis.Analyzer{
		Name: "wrapcheck",
		Doc:  "Checks that errors returned from external packages are wrapped",
		Run:  makeRun(cfg),
	}
}

// settings is the compiled form of Config used during a single pass.
type settings struct {
	sigs           []string
	sigRegexps     []*regexp.Regexp
	ifaceRegexps   []*regexp.Regexp
	pkgGlobs       []*globPattern
	reportInternal bool
}

func compileRegexps(list []string) ([]*regexp.Regexp, error) {
	out := make([]*regexp.Regexp, 0, len(list))
	for _, s := range list {
		re, err := regexp.Compile(s)
		if err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %v\n", s, err)
		}
		out = append(out, re)
	}
	return out, nil
}

func compileGlobs(list []string) ([]*globPattern, error) {
	out := make([]*globPattern, 0, len(list))
	for _, s := range list {
		g, err := compileGlob(s)
		if err != nil {
			return nil, fmt.Errorf("unable to compile globs %s: %v\n", "%!s(<nil>)", err)
		}
		out = append(out, g)
	}
	return out, nil
}

func makeRun(cfg Config) func(*analysis.Pass) (interface{}, error) {
	return func(pass *analysis.Pass) (interface{}, error) {
		sigRes, err := compileRegexps(cfg.IgnoreSigRegexps)
		if err != nil {
			return nil, err
		}
		ifaceRes, err := compileRegexps(cfg.IgnoreInterfaceRegexps)
		if err != nil {
			return nil, err
		}
		globs, err := compileGlobs(cfg.IgnorePackageGlobs)
		if err != nil {
			return nil, err
		}

		st := &settings{
			sigs:           append(append([]string{}, cfg.IgnoreSigs...), cfg.ExtraIgnoreSigs...),
			sigRegexps:     sigRes,
			ifaceRegexps:   ifaceRes,
			pkgGlobs:       globs,
			reportInternal: cfg.ReportInternalErrors,
		}

		for _, file := range pass.Files {
			w := &walker{pass: pass, file: file, st: st}
			w.walk()
		}
		return nil, nil
	}
}

type walker struct {
	pass *analysis.Pass
	file *ast.File
	st   *settings

	// funcs is the stack of enclosing function nodes (FuncDecl or FuncLit).
	funcs []ast.Node
}

func (w *walker) walk() {
	ast.Inspect(w.file, func(n ast.Node) bool {
		if n == nil {
			// Leaving a node; pop function stack if needed.
			return true
		}
		return true
	})

	var visit func(n ast.Node) bool
	var stack []ast.Node
	visit = func(n ast.Node) bool {
		if n == nil {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			switch top.(type) {
			case *ast.FuncDecl, *ast.FuncLit:
				w.funcs = w.funcs[:len(w.funcs)-1]
			}
			return true
		}
		stack = append(stack, n)
		switch n := n.(type) {
		case *ast.FuncDecl, *ast.FuncLit:
			w.funcs = append(w.funcs, n)
		case *ast.ReturnStmt:
			w.checkReturn(n)
		}
		return true
	}
	ast.Inspect(w.file, visit)
}

func (w *walker) inFuncLit() bool {
	if len(w.funcs) == 0 {
		return false
	}
	_, ok := w.funcs[len(w.funcs)-1].(*ast.FuncLit)
	return ok
}

func isError(t types.Type) bool {
	return t != nil && t.String() == "error"
}

func (w *walker) checkReturn(ret *ast.ReturnStmt) {
	if len(ret.Results) < 1 {
		return
	}
	info := w.pass.TypesInfo

	for _, expr := range ret.Results {
		if call, ok := expr.(*ast.CallExpr); ok {
			typ := info.TypeOf(expr)
			if isError(typ) {
				if !w.inFuncLit() {
					w.report(call, call.Pos())
				}
				return
			}
			tup, ok := typ.(*types.Tuple)
			if !ok {
				return
			}
			for i := 0; i < tup.Len(); i++ {
				if isError(tup.At(i).Type()) {
					if !w.inFuncLit() {
						w.report(call, call.Pos())
					}
					return
				}
			}
			return
		}

		if !isError(info.TypeOf(expr)) {
			continue
		}

		ident, ok := expr.(*ast.Ident)
		if !ok {
			return
		}

		var call *ast.CallExpr
		if ass := w.prevErrAssign(ident); ass != nil {
			c, ok := ass.Rhs[0].(*ast.CallExpr)
			if !ok {
				return
			}
			call = c
		} else if w.isUnresolved(ident) {
			return
		} else {
			if ident.Obj == nil {
				return
			}
			spec, ok := ident.Obj.Decl.(*ast.ValueSpec)
			if !ok {
				return
			}
			if len(spec.Values) < 1 {
				return
			}
			c, ok := spec.Values[0].(*ast.CallExpr)
			if !ok {
				return
			}
			call = c
		}
		if call == nil {
			return
		}
		w.report(call, ident.NamePos)
	}
}

// prevErrAssign finds the most recent assignment statement in the file,
// positioned before the identifier, which assigns to the same object.
func (w *walker) prevErrAssign(ident *ast.Ident) *ast.AssignStmt {
	if ident.Obj == nil {
		return nil
	}
	var found *ast.AssignStmt
	ast.Inspect(w.file, func(n ast.Node) bool {
		ass, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if ass.Pos() >= ident.Pos() {
			return true
		}
		for _, lhs := range ass.Lhs {
			if id, ok := lhs.(*ast.Ident); ok && id.Obj != nil && id.Obj == ident.Obj {
				found = ass
				break
			}
		}
		return true
	})
	return found
}

func (w *walker) isUnresolved(ident *ast.Ident) bool {
	for _, u := range w.file.Unresolved {
		if u.Pos() == ident.Pos() {
			return true
		}
	}
	return false
}

func (w *walker) sigIgnored(sig string) bool {
	for _, s := range w.st.sigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, re := range w.st.sigRegexps {
		if re.MatchString(sig) {
			return true
		}
	}
	return false
}

func pkgPath(obj types.Object) string {
	if obj == nil || obj.Pkg() == nil {
		return ""
	}
	return obj.Pkg().Path()
}

func (w *walker) globIgnored(path string) bool {
	for _, g := range w.st.pkgGlobs {
		if g.Match(path) {
			return true
		}
	}
	return false
}

func (w *walker) report(call *ast.CallExpr, pos tokenPos) {
	info := w.pass.TypesInfo
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		obj := info.ObjectOf(fun.Sel)
		if obj == nil {
			return
		}
		sig := obj.String()
		if w.sigIgnored(sig) {
			return
		}
		globbed := w.globIgnored(pkgPath(obj))

		if !globbed {
			if xt := info.TypeOf(fun.X); xt != nil {
				if _, isIface := xt.Underlying().(*types.Interface); isIface {
					name := types.TypeString(xt, func(p *types.Package) string { return p.Name() })
					matched := false
					for _, re := range w.st.ifaceRegexps {
						if re.MatchString(name) {
							matched = true
							break
						}
					}
					if !matched {
						w.pass.Reportf(pos, msgInterface, sig)
						return
					}
				}
			}
			if pkgPath(obj) != w.pass.Pkg.Path() {
				w.pass.Reportf(pos, msgExternal, sig)
				return
			}
		}
		if w.st.reportInternal {
			w.pass.Reportf(pos, msgInternal, sig)
		}
	case *ast.Ident:
		obj := info.ObjectOf(fun)
		if obj == nil {
			return
		}
		sig := obj.String()
		if w.sigIgnored(sig) {
			return
		}
		if w.st.reportInternal {
			w.pass.Reportf(pos, msgInternal, sig)
		}
	}
}
EOF
