			continue
		}

		ident, ok := expr.(*ast.Ident)
		if !ok {
			return
		}

		var call *ast.CallExpr
		if ass := w.prevErrAssign(ident); ass != nil {
			c, ok := ass.Rhs[0].(*ast.CallExpr)
			if !ok {
				return
			}
			call = c
		} else if w.isUnresolved(ident) {
			return
		} else {
			if ident.Obj == nil {
				return
			}
			spec, ok := ident.Obj.Decl.(*ast.ValueSpec)
			if !ok {
				return
			}
			if len(spec.Values) < 1 {
				return
			}
			c, ok := spec.Values[0].(*ast.CallExpr)
			if !ok {
				return
			}
			call = c
		}
		if call == nil {
			return
		}
		w.report(call, ident.NamePos)
	}
}

// prevErrAssign finds the most recent assignment statement in the file,
// positioned before the identifier, which assigns to the same object.
func (w *walker) prevErrAssign(ident *ast.Ident) *ast.AssignStmt {
	if ident.Obj == nil {
		return nil
	}
	var found *ast.AssignStmt
	ast.Inspect(w.file, func(n ast.Node) bool {
		ass, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if ass.Pos() >= ident.Pos() {
			return true
		}
		for _, lhs := range ass.Lhs {
			if id, ok := lhs.(*ast.Ident); ok && id.Obj != nil && id.Obj == ident.Obj {
				found = ass
				break
			}
		}
		return true
	})
	return found
}

func (w *walker) isUnresolved(ident *ast.Ident) bool {
	for _, u := range w.file.Unresolved {
		if u.Pos() == ident.Pos() {
			return true
		}
	}
	return false
}

func (w *walker) sigIgnored(sig string) bool {
	for _, s := range w.st.sigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, re := range w.st.sigRegexps {
		if re.MatchString(sig) {
			return true
		}
	}
	return false
}

func pkgPath(obj types.Object) string {
	if obj == nil || obj.Pkg() == nil {
		return ""
	}
	return obj.Pkg().Path()
}

func (w *walker) globIgnored(path string) bool {
	for _, g := range w.st.pkgGlobs {
		if g.Match(path) {
			return true
		}
	}
	return false
}

func (w *walker) report(call *ast.CallExpr, pos tokenPos) {
	info := w.pass.TypesInfo
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		obj := info.ObjectOf(fun.Sel)
		if obj == nil {
			return
		}
		sig := obj.String()
		if w.sigIgnored(sig) {
			return
		}
		globbed := w.globIgnored(pkgPath(obj))

		if !globbed {
			if xt := info.TypeOf(fun.X); xt != nil {
				if _, isIface := xt.Underlying().(*types.Interface); isIface {
					name := types.TypeString(xt, func(p *types.Package) string { return p.Name() })
					matched := false
					for _, re := range w.st.ifaceRegexps {
						if re.MatchString(name) {
							matched = true
							break
						}
					}
					if !matched {
						w.pass.Reportf(pos, msgInterface, sig)
						return
					}
				}
			}
			if pkgPath(obj) != w.pass.Pkg.Path() {
				w.pass.Reportf(pos, msgExternal, sig)
				return
			}
		}
		if w.st.reportInternal {
			w.pass.Reportf(pos, msgInternal, sig)
		}
	case *ast.Ident:
		obj := info.ObjectOf(fun)
		if obj == nil {
			return
		}
		sig := obj.String()
		if w.sigIgnored(sig) {
			return
		}
		if w.st.reportInternal {
			w.pass.Reportf(pos, msgInternal, sig)
		}
	}
}
