{"command":"cd /workspace && cat > glob.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strings"
	"unicode/utf8"
)

// This file implements shell-like glob patterns used for the
// ignorePackageGlobs option. Supported syntax:
//
//	*        any sequence of characters
//	**       any sequence of characters
//	?        any single character
//	[abc]    character class, [!abc] negated class
//	[a-z]    character range, [!a-z] negated range
//	{a,b}    alternatives
//	\c       literal character c

type globTokKind int

const (
	gtEOF globTokKind = iota
	gtError
	gtText
	gtAny
	gtSuper
	gtSingle
	gtNot
	gtSeparator
	gtRangeOpen
	gtRangeClose
	gtRangeLo
	gtRangeHi
	gtRangeBetween
	gtTermsOpen
	gtTermsClose
)

type globTok struct {
	kind globTokKind
	raw  string
}

const globEOF rune = 0

type globLexer struct {
	data string
	pos  int
	err  error

	tokens     []globTok
	termsLevel int

	lastRune     rune
	lastRuneSize int
	hasRune      bool
}

func (l *globLexer) next() globTok {
	for {
		if l.err != nil {
			return globTok{gtError, l.err.Error()}
		}
		if len(l.tokens) > 0 {
			t := l.tokens[0]
			l.tokens = l.tokens[1:]
			return t
		}
		l.fetchItem()
	}
}

func (l *globLexer) push(k globTokKind, raw string) {
	l.tokens = append(l.tokens, globTok{k, raw})
}

func (l *globLexer) peek() (rune, int) {
	if l.pos == len(l.data) {
		return globEOF, 0
	}
	r, w := utf8.DecodeRuneInString(l.data[l.pos:])
	if r == utf8.RuneError {
		l.err = errors.New("could not read rune")
		return globEOF, 0
	}
	return r, w
}

func (l *globLexer) read() rune {
	if l.hasRune {
		l.hasRune = false
		l.pos += l.lastRuneSize
		return l.lastRune
	}
	r, s := l.peek()
	l.pos += s
	l.lastRune = r
	l.lastRuneSize = s
	return r
}

func (l *globLexer) unread() {
	if l.hasRune {
		l.err = errors.New("could not unread rune")
		return
	}
	l.pos -= l.lastRuneSize
	l.hasRune = true
}

var globTextBreakers = []rune{'?', '*', '[', '{'}
var globTermsBreakers = []rune{'?', '*', '[', '{', '}', ','}

func runeIn(list []rune, r rune) bool {
	for _, x := range list {
		if x == r {
			return true
		}
	}
	return false
}

func (l *globLexer) fetchItem() {
	r := l.read()
	switch {
	case r == globEOF:
		l.push(gtEOF, "")
	case r == '{':
		l.termsLevel++
		l.push(gtTermsOpen, string(r))
	case r == ',' && l.termsLevel > 0:
		l.push(gtSeparator, string(r))
	case r == '}' && l.termsLevel > 0:
		l.push(gtTermsClose, string(r))
		l.termsLevel--
	case r == '[':
		l.push(gtRangeOpen, string(r))
		l.fetchRange()
	case r == '?':
		l.push(gtSingle, string(r))
	case r == '*':
		if l.read() == '*' {
			l.push(gtSuper, "**")
		} else {
			l.unread()
			l.push(gtAny, "*")
		}
	default:
		l.unread()
		if l.termsLevel > 0 {
			l.fetchText(globTermsBreakers)
		} else {
			l.fetchText(globTextBreakers)
		}
	}
}

func (l *globLexer) fetchRange() {
	var wantHi, wantClose, seenNot bool
	for {
		r := l.read()
		if r == globEOF {
			l.err = errors.New("unexpected end of input")
			return
		}
		if wantClose {
			if r != ']' {
				l.err = errors.New("expected close range character")
			} else {
				l.push(gtRangeClose, string(r))
			}
			return
		}
		if wantHi {
			l.push(gtRangeHi, string(r))
			wantClose = true
			continue
		}
		if !seenNot && r == '!' {
			l.push(gtNot, string(r))
			seenNot = true
			continue
		}
		if n, w := l.peek(); n == '-' {
			l.pos += w
			l.push(gtRangeLo, string(r))
			l.push(gtRangeBetween, string(n))
			wantHi = true
			continue
		}
		l.unread()
		l.fetchText([]rune{']'})
		wantClose = true
	}
}

func (l *globLexer) fetchText(breakers []rune) {
	var data []rune
	escaped := false
	for {
		r := l.read()
		if r == globEOF {
			break
		}
		if !escaped {
			if r == '\\' {
				escaped = true
				continue
			}
			if runeIn(breakers, r) {
				l.unread()
				break
			}
		}
		escaped = false
		data = append(data, r)
	}
	if len(data) > 0 {
		l.push(gtText, string(data))
	}
}

// AST

type globNodeKind int

const (
	gnPattern globNodeKind = iota
	gnAnyOf
	gnText
	gnAny
	gnSuper
	gnSingle
	gnList
	gnRange
)

type globNode struct {
	kind     globNodeKind
	parent   *globNode
	children []*globNode

	text  string
	chars string
	lo    rune
	hi    rune
	not   bool
}

func (n *globNode) insert(c *globNode) {
	c.parent = n
	n.children = append(n.children, c)
}

func parseGlob(src string) (*globNode, error) {
	lex := &globLexer{data: src}
	root := &globNode{kind: gnPattern}
	tree := root
	for {
		tok := lex.next()
		switch tok.kind {
		case gtEOF:
			return root, nil
		case gtError:
			return nil, errors.New(tok.raw)
		case gtText:
			tree.insert(&globNode{kind: gnText, text: tok.raw})
		case gtAny:
			tree.insert(&globNode{kind: gnAny})
		case gtSuper:
			tree.insert(&globNode{kind: gnSuper})
		case gtSingle:
			tree.insert(&globNode{kind: gnSingle})
		case gtRangeOpen:
			if err := parseGlobRange(tree, lex); err != nil {
				return nil, err
			}
		case gtTermsOpen:
			a := &globNode{kind: gnAnyOf}
			tree.insert(a)
			p := &globNode{kind: gnPattern}
			a.insert(p)
			tree = p
		case gtSeparator:
			p := &globNode{kind: gnPattern}
			tree.parent.insert(p)
			tree = p
		case gtTermsClose:
			tree = tree.parent.parent
		default:
			return nil, fmt.Errorf("unexpected token: %s", tok.raw)
		}
	}
}

func parseGlobRange(tree *globNode, lex *globLexer) error {
	var (
		not   bool
		lo    rune
		hi    rune
		chars string
	)
	for {
		tok := lex.next()
		switch tok.kind {
		case gtEOF:
			return errors.New("unexpected end")
		case gtError:
			return errors.New(tok.raw)
		case gtNot:
			not = true
		case gtRangeLo:
			r, w := utf8.DecodeRuneInString(tok.raw)
			if len(tok.raw) > w {
				return errors.New("unexpected length of lo character")
			}
			lo = r
		case gtRangeBetween:
		case gtRangeHi:
			r, w := utf8.DecodeRuneInString(tok.raw)
			if len(tok.raw) > w {
				return errors.New("unexpected length of lo character")
			}
			hi = r
			if hi < lo {
				return fmt.Errorf("hi character '%s' should be greater than lo '%s'", string(hi), string(lo))
			}
		case gtText:
			chars = tok.raw
		case gtRangeClose:
			isRange := lo != 0 && hi != 0
			isChars := chars != ""
			if isChars == isRange {
				return errors.New("could not parse range")
			}
			if isRange {
				tree.insert(&globNode{kind: gnRange, lo: lo, hi: hi, not: not})
			} else {
				tree.insert(&globNode{kind: gnList, chars: chars, not: not})
			}
			return nil
		}
	}
}

// Matching

type globPattern struct {
	root *globNode
}

func compileGlob(src string) (*globPattern, error) {
	root, err := parseGlob(src)
	if err != nil {
		return nil, err
	}
	return &globPattern{root: root}, nil
}

// Match reports whether the whole string s matches the pattern.
func (g *globPattern) Match(s string) bool {
	return matchSeq(g.root.children, s, func(rest string) bool { return rest == "" })
}

// matchSeq matches the sequence of nodes against a prefix of s and calls k
// with the remaining input for every possible way of matching.
func matchSeq(nodes []*globNode, s string, k func(string) bool) bool {
	if len(nodes) == 0 {
		return k(s)
	}
	n := nodes[0]
	rest := nodes[1:]
	switch n.kind {
	case gnText:
		if strings.HasPrefix(s, n.text) {
			return matchSeq(rest, s[len(n.text):], k)
		}
		return false
	case gnAny, gnSuper:
		// Try every split point (rune boundaries).
		i := 0
		for {
			if matchSeq(rest, s[i:], k) {
				return true
			}
			if i >= len(s) {
				return false
			}
			_, w := utf8.DecodeRuneInString(s[i:])
			i += w
		}
	case gnSingle:
		if s == "" {
			return false
		}
		_, w := utf8.DecodeRuneInString(s)
		return matchSeq(rest, s[w:], k)
	case gnList:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := strings.ContainsRune(n.chars, r)
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:], k)
	case gnRange:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := r >= n.lo && r <= n.hi
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:], k)
	case gnAnyOf:
		for _, alt := range n.children {
			if matchSeq(alt.children, s, func(r string) bool { return matchSeq(rest, r, k) }) {
				return true
			}
		}
		return false
	case gnPattern:
		return matchSeq(n.children, s, func(r string) bool { return matchSeq(rest, r, k) })
	}
	return false
}
