			return nil, fmt.Errorf("unexpected token: %s", tok.raw)
		}
	}
}

func parseGlobRange(tree *globNode, lex *globLexer) error {
	var (
		not   bool
		lo    rune
		hi    rune
		chars string
	)
	for {
		tok := lex.next()
		switch tok.kind {
		case gtEOF:
			return errors.New("unexpected end")
		case gtError:
			return errors.New(tok.raw)
		case gtNot:
			not = true
		case gtRangeLo:
			r, w := utf8.DecodeRuneInString(tok.raw)
			if len(tok.raw) > w {
				return errors.New("unexpected length of lo character")
			}
			lo = r
		case gtRangeBetween:
		case gtRangeHi:
			r, w := utf8.DecodeRuneInString(tok.raw)
			if len(tok.raw) > w {
				return errors.New("unexpected length of lo character")
			}
			hi = r
			if hi < lo {
				return fmt.Errorf("hi character '%s' should be greater than lo '%s'", string(hi), string(lo))
			}
		case gtText:
			chars = tok.raw
		case gtRangeClose:
			isRange := lo != 0 && hi != 0
			isChars := chars != ""
			if isChars == isRange {
				return errors.New("could not parse range")
			}
			if isRange {
				tree.insert(&globNode{kind: gnRange, lo: lo, hi: hi, not: not})
			} else {
				tree.insert(&globNode{kind: gnList, chars: chars, not: not})
			}
			return nil
		}
	}
}

// Matching

type globPattern struct {
	root *globNode
}

func compileGlob(src string) (*globPattern, error) {
	root, err := parseGlob(src)
	if err != nil {
		return nil, err
	}
	return &globPattern{root: root}, nil
}

// Match reports whether the whole string s matches the pattern.
func (g *globPattern) Match(s string) bool {
	return matchSeq(g.root.children, s, func(rest string) bool { return rest == "" })
}

// matchSeq matches the sequence of nodes against a prefix of s and calls k
// with the remaining input for every possible way of matching.
func matchSeq(nodes []*globNode, s string, k func(string) bool) bool {
	if len(nodes) == 0 {
		return k(s)
	}
	n := nodes[0]
	rest := nodes[1:]
	switch n.kind {
	case gnText:
		if strings.HasPrefix(s, n.text) {
			return matchSeq(rest, s[len(n.text):], k)
		}
		return false
	case gnAny, gnSuper:
		// Try every split point (rune boundaries).
		i := 0
		for {
			if matchSeq(rest, s[i:], k) {
				return true
			}
			if i >= len(s) {
				return false
			}
			_, w := utf8.DecodeRuneInString(s[i:])
			i += w
		}
	case gnSingle:
		if s == "" {
			return false
		}
		_, w := utf8.DecodeRuneInString(s)
		return matchSeq(rest, s[w:], k)
	case gnList:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := strings.ContainsRune(n.chars, r)
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:], k)
	case gnRange:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := r >= n.lo && r <= n.hi
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:], k)
	case gnAnyOf:
		for _, alt := range n.children {
			if matchSeq(alt.children, s, func(r string) bool { return matchSeq(rest, r, k) }) {
				return true
			}
		}
		return false
	case gnPattern:
		return matchSeq(n.children, s, func(r string) bool { return matchSeq(rest, r, k) })
	}
	return false
}
EOF

