				dup = true
				break
			}
		}
		if !dup {
			dirs = append(dirs, abs)
		}
	}
	return dirs
}

func isRegularish(path string) bool {
	st, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !st.IsDir()
}

func findConfigFile() (string, error) {
	for _, dir := range searchDirs() {
		for _, ext := range configExts {
			p := filepath.Join(dir, configName+"."+ext)
			if isRegularish(p) {
				return p, nil
			}
		}
		p := filepath.Join(dir, configName)
		if isRegularish(p) {
			return p, nil
		}
	}
	return "", errConfigNotFound
}

// readConfigMap locates and parses the configuration file. It returns
// errConfigNotFound if no file exists.
func readConfigMap() (map[string]interface{}, error) {
	file, err := findConfigFile()
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(file)
	if err != nil {
		return nil, err
	}
	m := make(map[string]interface{})
	if err := decodeYAML(data, m); err != nil {
		return nil, fmt.Errorf("While parsing config: %s", err.Error())
	}
	lowerKeys(m)
	return m, nil
}

func decodeYAML(data []byte, v map[string]interface{}) error {
	var buf bytes.Buffer
	buf.Write(data)
	return yaml.Unmarshal(buf.Bytes(), &v)
}

func toStringMap(m map[interface{}]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(m))
	for k, v := range m {
		out[fmt.Sprintf("%v", k)] = v
	}
	return out
}

// lowerKeys lower-cases all keys of nested maps (but not of maps nested in
// lists), converting generic maps into string keyed maps on the way.
func lowerKeys(m map[string]interface{}) {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, key := range keys {
		val := m[key]
		switch v := val.(type) {
		case map[interface{}]interface{}:
			sm := toStringMap(v)
			lowerKeys(sm)
			val = sm
		case map[string]interface{}:
			lowerKeys(v)
		}
		lower := strings.ToLower(key)
		if key != lower {
			delete(m, key)
		}
		m[lower] = val
	}
}

// flattenKeys collects the dotted paths of all leaf values.
func flattenKeys(set map[string]bool, m map[string]interface{}, prefix string) {
	if prefix != "" && set[prefix] {
		return
	}
	if prefix != "" {
		prefix += "."
	}
	for k, val := range m {
		full := prefix + k
		var sub map[string]interface{}
		switch v := val.(type) {
		case map[string]interface{}:
			sub = v
		case map[interface{}]interface{}:
			sub = toStringMap(v)
		default:
			set[strings.ToLower(full)] = true
			continue
		}
		flattenKeys(set, sub, full)
	}
}

func searchPath(source interface{}, path []string) interface{} {
	if len(path) == 0 {
		return source
	}
	for i := len(path); i > 0; i-- {
		prefixKey := strings.ToLower(strings.Join(path[0:i], "."))
		var val interface{}
		switch src := source.(type) {
		case map[string]interface{}:
			next, ok := src[prefixKey]
			if !ok {
				break
			}
			if i == len(path) {
				val = next
				break
			}
			switch n := next.(type) {
			case map[interface{}]interface{}:
				val = searchPath(toStringMap(n), path[i:])
			case map[string]interface{}, []interface{}:
				val = searchPath(n, path[i:])
			}
		case []interface{}:
			idx, err := strconv.Atoi(prefixKey)
			if err != nil || idx < 0 || idx >= len(src) {
				break
			}
			next := src[idx]
			if i == len(path) {
				val = next
				break
			}
			switch n := next.(type) {
			case map[interface{}]interface{}:
				val = searchPath(toStringMap(n), path[i:])
			case map[string]interface{}, []interface{}:
				val = searchPath(n, path[i:])
			}
		}
		if val != nil {
			return val
		}
	}
	return nil
}

func deepMap(m map[string]interface{}, path []string) map[string]interface{} {
	for _, k := range path {
		m2, ok := m[k]
		if !ok {
			m3 := make(map[string]interface{})
			m[k] = m3
			m = m3
			continue
		}
		m3, ok := m2.(map[string]interface{})
		if !ok {
			m3 = make(map[string]interface{})
			m[k] = m3
		}
		m = m3
	}
	return m
}

// settingsFrom builds the effective settings map from the parsed
// configuration file and the built-in defaults.
func settingsFrom(cfg map[string]interface{}) map[string]interface{} {
	defaults := map[string]interface{}{
		"ignoresigs": append([]string{}, defaultIgnoreSigs...),
	}
	set := map[string]bool{}
	flattenKeys(set, cfg, "")
	flattenKeys(set, defaults, "")

	keys := make([]string, 0, len(set))
	for k := range set {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	out := map[string]interface{}{}
	for _, k := range keys {
		path := strings.Split(k, ".")
		val := searchPath(cfg, path)
		if val == nil {
			val = searchPath(defaults, path)
		}
		if val == nil {
			continue
		}
		last := strings.ToLower(path[len(path)-1])
		dm := deepMap(out, path[:len(path)-1])
		dm[last] = val
	}
	return out
}

// Decoding of the settings map into Config, with lenient type conversion.

type decodeErrors struct {
	errs []string
}

func (e *decodeErrors) Error() string {
	points := make([]string, len(e.errs))
	for i, err := range e.errs {
		points[i] = fmt.Sprintf("* %s", err)
	}
	sort.Strings(points)
	return fmt.Sprintf("%d error(s) decoding:\n\n%s", len(e.errs), strings.Join(points, "\n"))
}

func appendErrs(list []string, err error) []string {
	if de, ok := err.(*decodeErrors); ok {
		return append(list, de.errs...)
	}
	return append(list, err.Error())
}

type kindClass int

const (
	kcOther kindClass = iota
	kcBool
	kcInt
	kcUint
	kcFloat
	kcString
	kcSlice
	kcArray
	kcMap
)

func classify(v reflect.Value) kindClass {
	switch v.Kind() {
	case reflect.Bool:
		return kcBool
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return kcInt
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return kcUint
	case reflect.Float32, reflect.Float64:
		return kcFloat
	case reflect.String:
		return kcString
	case reflect.Slice:
		return kcSlice
	case reflect.Array:
		return kcArray
	case reflect.Map:
		return kcMap
	}
	return kcOther
}

func indirectValue(data interface{}) reflect.Value {
	return reflect.Indirect(reflect.ValueOf(data))
}

func isNilInput(data interface{}) bool {
	if data == nil {
		return true
	}
	v := reflect.ValueOf(data)
	return v.Kind() == reflect.Ptr && v.IsNil()
}

func decodeString(name string, data interface{}) (string, bool, error) {
	if isNilInput(data) {
		return "", false, nil
	}
	dv := indirectValue(data)
	switch classify(dv) {
	case kcString:
		return dv.String(), true, nil
	case kcBool:
		if dv.Bool() {
			return "1", true, nil
		}
		return "0", true, nil
	case kcInt:
		return strconv.FormatInt(dv.Int(), 10), true, nil
	case kcUint:
		return strconv.FormatUint(dv.Uint(), 10), true, nil
	case kcFloat:
		return strconv.FormatFloat(dv.Float(), 'f', -1, 64), true, nil
	case kcSlice, kcArray:
		if dv.Type().Elem().Kind() == reflect.Uint8 {
			b := make([]byte, dv.Len())
			for i := range b {
				b[i] = byte(dv.Index(i).Uint())
			}
			return string(b), true, nil
		}
	}
	return "", false, fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s', value: '%v'", name, "string", dv.Type(), data)
}

func decodeBool(name string, data interface{}) (bool, bool, error) {
	if isNilInput(data) {
		return false, false, nil
	}
	dv := indirectValue(data)
	switch classify(dv) {
	case kcBool:
		return dv.Bool(), true, nil
	case kcInt:
		return dv.Int() != 0, true, nil
	case kcUint:
		return dv.Uint() != 0, true, nil
	case kcFloat:
		return dv.Float() != 0, true, nil
	case kcString:
		b, err := strconv.ParseBool(dv.String())
		if err == nil {
			return b, true, nil
		}
		if dv.String() == "" {
			return false, true, nil
		}
		return false, false, fmt.Errorf("cannot parse '%s' as bool: %s", name, err)
	}
	return false, false, fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s', value: '%v'", name, "bool", dv.Type(), data)
}

// decodeStringSlice converts data into a list of strings. set reports
// whether the destination should be assigned.
func decodeStringSlice(name string, data interface{}) ([]string, bool, error) {
	if isNilInput(data) {
		return nil, false, nil
	}
	// A plain string is split on commas.
	if s, ok := data.(string); ok {
		if s == "" {
			data = []string{}
		} else {
			data = strings.Split(s, ",")
		}
	} else if reflect.ValueOf(data).Kind() == reflect.String {
		s := reflect.ValueOf(data).String()
		if s == "" {
			data = []string{}
		} else {
			data = strings.Split(s, ",")
		}
	}

	dv := indirectValue(data)
	kind := dv.Kind()
	if kind != reflect.Slice && kind != reflect.Array {
		if kind == reflect.Map {
			if dv.Len() == 0 {
				return []string{}, true, nil
			}
		}
		return decodeStringSlice(name, []interface{}{data})
	}
	if kind != reflect.Array && dv.IsNil() {
		return nil, false, nil
	}

	out := make([]string, dv.Len())
	var errs []string
	for i := 0; i < dv.Len(); i++ {
		elem := dv.Index(i).Interface()
		s, ok, err := decodeString(name+"["+strconv.Itoa(i)+"]", elem)
		if err != nil {
			errs = appendErrs(errs, err)
			continue
		}
		if ok {
			out[i] = s
		}
	}
	if len(errs) > 0 {
		return out, true, &decodeErrors{errs}
	}
	return out, true, nil
}

func lookupField(m map[string]interface{}, field string) (interface{}, bool) {
	if v, ok := m[field]; ok {
		return v, true
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		if strings.EqualFold(k, field) {
			return m[k], true
		}
	}
	return nil, false
}

func decodeConfig(m map[string]interface{}) (Config, error) {
	var cfg Config
	var errs []string

	sliceFields := []struct {
		name string
		dst  *[]string
	}{
		{"ignoreSigs", &cfg.IgnoreSigs},
		{"extraIgnoreSigs", &cfg.ExtraIgnoreSigs},
		{"ignoreSigRegexps", &cfg.IgnoreSigRegexps},
		{"ignorePackageGlobs", &cfg.IgnorePackageGlobs},
		{"ignoreInterfaceRegexps", &cfg.IgnoreInterfaceRegexps},
	}
	for _, f := range sliceFields {
		raw, ok := lookupField(m, f.name)
		if !ok {
			continue
		}
		v, set, err := decodeStringSlice(f.name, raw)
		if set {
			*f.dst = v
		}
		if err != nil {
			errs = appendErrs(errs, err)
		}
	}

	if raw, ok := lookupField(m, "reportInternalErrors"); ok {
		v, set, err := decodeBool("reportInternalErrors", raw)
		if set {
			cfg.ReportInternalErrors = v
		}
		if err != nil {
			errs = appendErrs(errs, err)
		}
	}

	if len(errs) > 0 {
		return cfg, &decodeErrors{errs}
	}
	return cfg, nil
}
EOF"}

