// topLevelKeyOrder returns the keys of m in the order in which they appear
// in the document (as far as it can be determined).
func topLevelKeyOrder(data []byte, m map[string]interface{}) []string {
	var order []string
	seen := map[string]bool{}
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err == nil && doc.Kind == yaml.DocumentNode && len(doc.Content) == 1 {
		root := doc.Content[0]
		if root.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(root.Content); i += 2 {
				k := root.Content[i].Value
				if _, ok := m[k]; ok && !seen[k] {
					seen[k] = true
					order = append(order, k)
				}
			}
		}
	}
	var rest []string
	for k := range m {
		if !seen[k] {
			rest = append(rest, k)
		}
	}
	sort.Strings(rest)
	return append(order, rest...)
}

// lowerTopLevel lower-cases the keys of the top-level map (and, recursively,
// of nested maps). Keys colliding after lower-casing are resolved the way an
// in-order traversal of a small hash map would resolve them.
func lowerTopLevel(m map[string]interface{}, order []string) map[string]interface{} {
	const groupSlots = 8
	if len(order) != len(m) || len(m) > groupSlots {
		lowerKeys(m)
		return m
	}
	type slot struct {
		key  string
		val  interface{}
		used bool
	}
	slots := make([]slot, groupSlots)
	for i, k := range order {
		slots[i] = slot{k, m[k], true}
	}
	set := func(k string, v interface{}) {
		for i := range slots {
			if slots[i].used && slots[i].key == k {
				slots[i].val = v
				return
			}
		}
		for i := range slots {
			if !slots[i].used {
				slots[i] = slot{k, v, true}
				return
			}
		}
	}
	for i := 0; i < groupSlots; i++ {
		if !slots[i].used {
			continue
		}
		key, val := slots[i].key, slots[i].val
		switch v := val.(type) {
		case map[interface{}]interface{}:
			sm := toStringMap(v)
			lowerKeys(sm)
			val = sm
		case map[string]interface{}:
			lowerKeys(v)
		}
		lower := strings.ToLower(key)
		if key != lower {
			slots[i].used = false
		}
		set(lower, val)
	}
	out := make(map[string]interface{}, len(m))
	for _, s := range slots {
		if s.used {
			out[s.key] = s.val
		}
	}
	return out
}
