	return inList == !m.not
}
func (m mList) Len() int { return lenOne }
func (m mList) Index(s string) (int, []int) {
	for i, r := range s {
		if m.not == (indexRune(m.list, r) == -1) {
			return i, segmentsByRuneLength[utf8.RuneLen(r)]
		}
	}
