type mAnyOf struct{ ms []globMatcher }

func (a mAnyOf) Match(s string) bool {
	for _, m := range a.ms {
		if m.Match(s) {
			return true
		}
	}
	return false
}

func appendMerge(target, sub []int) []int {
	lt, ls := len(target), len(sub)
	out := make([]int, 0, lt+ls)
	for x, y := 0, 0; x < lt || y < ls; {
		if x >= lt {
			out = append(out, sub[y:]...)
			break
		}
		if y >= ls {
			out = append(out, target[x:]...)
			break
		}
		xValue := target[x]
		yValue := sub[y]
		switch {
		case xValue == yValue:
			out = append(out, xValue)
			x++
			y++
		case xValue < yValue:
			out = append(out, xValue)
			x++
		case yValue < xValue:
			out = append(out, yValue)
			y++
		}
	}
	return append(target[:0], out...)
}

func (a mAnyOf) Index(s string) (int, []int) {
	index := -1
	segments := make([]int, 0, len(s))
	for _, m := range a.ms {
		idx, seg := m.Index(s)
		if idx == -1 {
			continue
		}
		if index == -1 || idx < index {
			index = idx
			segments = append(segments[:0], seg...)
			continue
		}
		if idx > index {
			continue
		}
		segments = appendMerge(segments, seg)
	}
	if index == -1 {
		return -1, nil
	}
	return index, segments
}

func (a mAnyOf) Len() (l int) {
	l = -1
	for _, m := range a.ms {
		ml := m.Len()
		switch {
		case l == -1:
			l = ml
			continue
		case ml == -1:
			return -1
		case l != ml:
			return -1
		}
	}
	return
}

type mEveryOf struct{ ms []globMatcher }

func (e mEveryOf) Len() (l int) {
	for _, m := range e.ms {
		if ml := m.Len(); l > 0 {
			l += ml
		} else {
			return -1
		}
	}
	return
}

func (e mEveryOf) Index(s string) (int, []int) {
	var index int
	var offset int
	next := make([]int, 0, len(s))
	current := make([]int, 0, len(s))
	sub := s
	for i, m := range e.ms {
		idx, seg := m.Index(sub)
		if idx == -1 {
			return -1, nil
		}
		if i == 0 {
			current = append(current, seg...)
		} else {
			next = next[:0]
			delta := index - (idx + offset)
			for _, ex := range current {
				for _, n := range seg {
					if ex+delta == n {
						next = append(next, n)
					}
				}
			}
			if len(next) == 0 {
				return -1, nil
			}
			current = append(current[:0], next...)
		}
		index = idx + offset
		sub = s[index:]
		offset += idx
	}
	return index, current
}

func (e mEveryOf) Match(s string) bool {
	for _, m := range e.ms {
		if !m.Match(s) {
			return false
		}
	}
	return true
}

type mMin struct{ limit int }

func (m mMin) Match(s string) bool {
	var l int
	for range s {
		l++
		if l >= m.limit {
			return true
		}
	}
	return false
}
func (m mMin) Index(s string) (int, []int) {
	var count int
	c := len(s) - m.limit + 1
	if c <= 0 {
		return -1, nil
	}
	segments := make([]int, 0, c)
	for i, r := range s {
		count++
		if count >= m.limit {
			segments = append(segments, i+utf8.RuneLen(r))
		}
	}
	if len(segments) == 0 {
		return -1, nil
	}
	return 0, segments
}
func (m mMin) Len() int { return lenNo }

type mMax struct{ limit int }

func (m mMax) Match(s string) bool {
	var l int
	for range s {
		l++
		if l > m.limit {
			return false
		}
	}
	return true
}
func (m mMax) Index(s string) (int, []int) {
	segments := make([]int, 0, m.limit+1)
	segments = append(segments, 0)
	var count int
	for i, r := range s {
		count++
		if count > m.limit {
			break
		}
		segments = append(segments, i+utf8.RuneLen(r))
	}
	return 0, segments
}
func (m mMax) Len() int { return lenNo }

type mContains struct {
	needle string
	not    bool
}

func (c mContains) Match(s string) bool { return strings.Contains(s, c.needle) != c.not }
func (c mContains) Index(s string) (int, []int) {
	var offset int
	idx := strings.Index(s, c.needle)
	if !c.not {
		if idx == -1 {
			return -1, nil
		}
		offset = idx + len(c.needle)
		if len(s) <= offset {
			return 0, []int{offset}
		}
		s = s[offset:]
	} else if idx != -1 {
		s = s[:idx]
	}
	segments := make([]int, 0, len(s)+1)
	for i := range s {
		segments = append(segments, offset+i)
	}
	return 0, append(segments, offset+len(s))
}
func (c mContains) Len() int { return lenNo }

type mPrefix struct{ prefix string }

func (p mPrefix) Index(s string) (int, []int) {
	idx := strings.Index(s, p.prefix)
	if idx == -1 {
		return -1, nil
	}
	length := len(p.prefix)
	var sub string
	if len(s) > idx+length {
		sub = s[idx+length:]
	} else {
		sub = ""
	}
	segments := make([]int, 0, len(sub)+1)
	segments = append(segments, length)
	for i, r := range sub {
		segments = append(segments, length+i+utf8.RuneLen(r))
	}
	return idx, segments
}
func (p mPrefix) Len() int            { return lenNo }
func (p mPrefix) Match(s string) bool { return strings.HasPrefix(s, p.prefix) }

type mSuffix struct{ suffix string }

func (p mSuffix) Len() int            { return lenNo }
func (p mSuffix) Match(s string) bool { return strings.HasSuffix(s, p.suffix) }
func (p mSuffix) Index(s string) (int, []int) {
	idx := strings.Index(s, p.suffix)
	if idx == -1 {
		return -1, nil
	}
	return 0, []int{idx + len(p.suffix)}
}

type mPrefixAny struct {
	prefix string
	seps   []rune
}

func (p mPrefixAny) Index(s string) (int, []int) {
	idx := strings.Index(s, p.prefix)
	if idx == -1 {
		return -1, nil
	}
	n := len(p.prefix)
	sub := s[idx+n:]
	if i := indexAnyRunes(sub, p.seps); i > -1 {
		sub = sub[:i]
	}
	seg := make([]int, 0, len(sub)+1)
	seg = append(seg, n)
	for i, r := range sub {
		seg = append(seg, n+i+utf8.RuneLen(r))
	}
	return idx, seg
}
func (p mPrefixAny) Len() int { return lenNo }
func (p mPrefixAny) Match(s string) bool {
	if !strings.HasPrefix(s, p.prefix) {
		return false
	}
	return indexAnyRunes(s[len(p.prefix):], p.seps) == -1
}

type mSuffixAny struct {
	suffix string
	seps   []rune
}

func (p mSuffixAny) Index(s string) (int, []int) {
	idx := strings.Index(s, p.suffix)
	if idx == -1 {
		return -1, nil
	}
	i := lastIndexAnyRunes(s[:idx], p.seps) + 1
	return i, []int{idx + len(p.suffix) - i}
}
func (p mSuffixAny) Len() int { return lenNo }
func (p mSuffixAny) Match(s string) bool {
	if !strings.HasSuffix(s, p.suffix) {
		return false
	}
	return indexAnyRunes(s[:len(s)-len(p.suffix)], p.seps) == -1
}

func lastIndexAnyRunes(s string, rs []rune) int {
	for _, r := range rs {
		i := -1
		if 0 <= r && r < utf8.RuneSelf {
			i = strings.LastIndexByte(s, byte(r))
		} else {
			sub := s
			for len(sub) > 0 {
				j := strings.IndexRune(s, r)
				if j == -1 {
					break
				}
				i = j
				sub = sub[i+1:]
			}
		}
		if i != -1 {
			return i
		}
	}
	return -1
}

type mPrefixSuffix struct{ prefix, suffix string }

func (p mPrefixSuffix) Index(s string) (int, []int) {
	prefixIdx := strings.Index(s, p.prefix)
	if prefixIdx == -1 {
		return -1, nil
	}
	suffixLen := len(p.suffix)
	if suffixLen <= 0 {
		return prefixIdx, []int{len(s) - prefixIdx}
	}
	if (len(s) - prefixIdx) <= 0 {
		return -1, nil
	}
	segments := make([]int, 0, len(s)-prefixIdx)
	for sub := s[prefixIdx:]; ; {
		suffixIdx := strings.LastIndex(sub, p.suffix)
		if suffixIdx == -1 {
			break
		}
		segments = append(segments, suffixIdx+suffixLen)
		sub = sub[:suffixIdx]
	}
	if len(segments) == 0 {
		return -1, nil
	}
	for i, j := 0, len(segments)-1; i < j; i, j = i+1, j-1 {
		segments[i], segments[j] = segments[j], segments[i]
	}
	return prefixIdx, segments
}
func (p mPrefixSuffix) Len() int { return lenNo }
func (p mPrefixSuffix) Match(s string) bool {
	return strings.HasPrefix(s, p.prefix) && strings.HasSuffix(s, p.suffix)
}

type mRow struct {
	ms          []globMatcher
	runesLength int
	segments    []int
}

func newRow(l int, m ...globMatcher) mRow {
	return mRow{ms: m, runesLength: l, segments: []int{l}}
}

func (r mRow) matchAll(s string) bool {
	var idx int
	for _, m := range r.ms {
		length := m.Len()
		var next, i int
		for next = range s[idx:] {
			i++
			if i == length {
				break
			}
		}
		if i < length || !m.Match(s[idx:idx+next+1]) {
			return false
		}
		idx += next + 1
	}
	return true
}

func (r mRow) lenOk(s string) bool {
	var i int
	for range s {
		i++
		if i > r.runesLength {
			return false
		}
	}
	return r.runesLength == i
}

func (r mRow) Match(s string) bool { return r.lenOk(s) && r.matchAll(s) }
func (r mRow) Len() int            { return r.runesLength }
func (r mRow) Index(s string) (int, []int) {
	for i := range s {
		if len(s[i:]) < r.runesLength {
			break
		}
		if r.matchAll(s[i:]) {
			return i, r.segments
		}
	}
	return -1, nil
}

type mBTree struct {
	value, left, right globMatcher

	valueLengthRunes int
	leftLengthRunes  int
	rightLengthRunes int
	lengthRunes      int
}

func newBTree(value, left, right globMatcher) mBTree {
	t := mBTree{value: value, left: left, right: right}
	lenOk := true
	if t.valueLengthRunes = value.Len(); t.valueLengthRunes == -1 {
		lenOk = false
	}
	if left != nil {
		if t.leftLengthRunes = left.Len(); t.leftLengthRunes == -1 {
			lenOk = false
		}
	}
	if right != nil {
		if t.rightLengthRunes = right.Len(); t.rightLengthRunes == -1 {
			lenOk = false
		}
	}
	if lenOk {
		t.lengthRunes = t.leftLengthRunes + t.valueLengthRunes + t.rightLengthRunes
	} else {
		t.lengthRunes = -1
	}
	return t
}

func (t mBTree) Len() int                  { return t.lengthRunes }
func (t mBTree) Index(string) (int, []int) { return -1, nil }

func (t mBTree) Match(s string) bool {
	inputLen := len(s)
	if t.lengthRunes != -1 && t.lengthRunes > inputLen {
		return false
	}

	var offset, limit int
	if t.leftLengthRunes >= 0 {
		offset = t.leftLengthRunes
	}
	if t.rightLengthRunes >= 0 {
		limit = inputLen - t.rightLengthRunes
	} else {
		limit = inputLen
	}

	for offset < limit {
		index, segments := t.value.Index(s[offset:limit])
		if index == -1 {
			return false
		}

		l := s[:offset+index]
		var left bool
		if t.left != nil {
			left = t.left.Match(l)
		} else {
			left = l == ""
		}

		if left {
			for i := len(segments) - 1; i >= 0; i-- {
				length := segments[i]
				var right bool
				var r string
				if inputLen <= offset+index+length {
					r = ""
				} else {
					r = s[offset+index+length:]
				}
				if t.right != nil {
					right = t.right.Match(r)
				} else {
					right = r == ""
				}
				if right {
					return true
				}
			}
		}

		_, step := utf8.DecodeRuneInString(s[offset+index:])
		offset += index + step
	}
	return false
}
