// Compilation of the syntax tree into matchers.

const (
	lenNo   = -1
	lenZero = 0
	lenOne  = 1
)

type globMatcher interface {
	Match(string) bool
	Index(string) (int, []int)
	Len() int
}

type globPattern struct {
	m globMatcher
}

func compileGlob(src string) (*globPattern, error) {
	root, err := parseGlob(src)
	if err != nil {
		return nil, err
	}
	m, err := compileGlobNode(root)
	if err != nil {
		return nil, err
	}
	return &globPattern{m: m}, nil
}

// Match reports whether the string s matches the pattern.
func (g *globPattern) Match(s string) bool {
	return g.m.Match(s)
}

func (n *globNode) equal(b *globNode) bool {
	if n.kind != b.kind {
		return false
	}
	if n.text != b.text || n.chars != b.chars || n.lo != b.lo || n.hi != b.hi || n.not != b.not {
		return false
	}
	if len(n.children) != len(b.children) {
		return false
	}
	for i, c := range n.children {
		if !c.equal(b.children[i]) {
			return false
		}
	}
	return true
}

func newGlobNode(kind globNodeKind, children ...*globNode) *globNode {
	n := &globNode{kind: kind}
	for _, c := range children {
		n.insert(c)
	}
	return n
}

const gnNothing globNodeKind = 100

func areOfSameKind(nodes []*globNode, kind globNodeKind) bool {
	for _, n := range nodes {
		if n.kind != kind {
			return false
		}
	}
	return true
}

func leastChildren(nodes []*globNode) int {
	min := -1
	idx := -1
	for i, n := range nodes {
		if idx == -1 || len(n.children) < min {
			min = len(n.children)
			idx = i
		}
	}
	return idx
}

func commonChildren(nodes []*globNode) (commonLeft, commonRight []*globNode) {
	if len(nodes) <= 1 {
		return
	}
	idx := leastChildren(nodes)
	if idx == -1 {
		return
	}
	tree := nodes[idx]
	treeLength := len(tree.children)

	commonRight = make([]*globNode, treeLength)
	lastRight := treeLength

	var (
		breakLeft   bool
		breakRight  bool
		commonTotal int
	)
	for i, j := 0, treeLength-1; commonTotal < treeLength && j >= 0 && !(breakLeft && breakRight); i, j = i+1, j-1 {
		treeLeft := tree.children[i]
		treeRight := tree.children[j]

		for k := 0; k < len(nodes) && !(breakLeft && breakRight); k++ {
			if k == idx {
				continue
			}
			restLeft := nodes[k].children[i]
			restRight := nodes[k].children[j+len(nodes[k].children)-treeLength]

			breakLeft = breakLeft || !treeLeft.equal(restLeft)
			breakRight = breakRight || (!breakLeft && j <= i)
			breakRight = breakRight || !treeRight.equal(restRight)
		}

		if !breakLeft {
			commonTotal++
			commonLeft = append(commonLeft, treeLeft)
		}
		if !breakRight {
			commonTotal++
			lastRight = j
			commonRight[j] = treeRight
		}
	}
	commonRight = commonRight[lastRight:]
	return
}

func appendIfUnique(target []*globNode, val *globNode) []*globNode {
	for _, n := range target {
		if n.equal(val) {
			return target
		}
	}
	return append(target, val)
}

func minimizeTreeAnyOf(tree *globNode) *globNode {
	if !areOfSameKind(tree.children, gnPattern) {
		return nil
	}
	commonLeft, commonRight := commonChildren(tree.children)
	commonLeftCount, commonRightCount := len(commonLeft), len(commonRight)
	if commonLeftCount == 0 && commonRightCount == 0 {
		return nil
	}

	var result []*globNode
	if commonLeftCount > 0 {
		result = append(result, newGlobNode(gnPattern, commonLeft...))
	}

	var anyOf []*globNode
	for _, child := range tree.children {
		reuse := child.children[commonLeftCount : len(child.children)-commonRightCount]
		var node *globNode
		if len(reuse) == 0 {
			node = newGlobNode(gnNothing)
		} else {
			node = newGlobNode(gnPattern, reuse...)
		}
		anyOf = appendIfUnique(anyOf, node)
	}
	switch len(anyOf) {
	case 0:
	case 1:
		result = append(result, anyOf[0])
	default:
		result = append(result, newGlobNode(gnAnyOf, anyOf...))
	}

	if commonRightCount > 0 {
		result = append(result, newGlobNode(gnPattern, commonRight...))
	}
	return newGlobNode(gnPattern, result...)
}

func compileGlobChildren(tree *globNode) ([]globMatcher, error) {
	var matchers []globMatcher
	for _, desc := range tree.children {
		m, err := compileGlobNode(desc)
		if err != nil {
			return nil, err
		}
		matchers = append(matchers, optimizeMatcher(m))
	}
	return matchers, nil
}

func compileGlobNode(tree *globNode) (globMatcher, error) {
	var m globMatcher
	switch tree.kind {
	case gnAnyOf:
		if n := minimizeTreeAnyOf(tree); n != nil {
			return compileGlobNode(n)
		}
		matchers, err := compileGlobChildren(tree)
		if err != nil {
			return nil, err
		}
		return mAnyOf{matchers}, nil
	case gnPattern:
		if len(tree.children) == 0 {
			return mNothing{}, nil
		}
		matchers, err := compileGlobChildren(tree)
		if err != nil {
			return nil, err
		}
		m, err = compileMatchers(minimizeMatchers(matchers))
		if err != nil {
			return nil, err
		}
	case gnAny:
		m = mAny{}
	case gnSuper:
		m = mSuper{}
	case gnSingle:
		m = mSingle{}
	case gnNothing:
		m = mNothing{}
	case gnList:
		m = mList{list: []rune(tree.chars), not: tree.not}
	case gnRange:
		m = mRange{lo: tree.lo, hi: tree.hi, not: tree.not}
	case gnText:
		m = newText(tree.text)
	default:
		return nil, errors.New("could not compile tree: unknown node type")
	}
	return optimizeMatcher(m), nil
}

func optimizeMatcher(matcher globMatcher) globMatcher {
	switch m := matcher.(type) {
	case mAny:
		if len(m.seps) == 0 {
			return mSuper{}
		}
	case mAnyOf:
		if len(m.ms) == 1 {
			return m.ms[0]
		}
		return m
	case mList:
		if !m.not && len(m.list) == 1 {
			return newText(string(m.list))
		}
		return m
	case mBTree:
		m.left = optimizeMatcher(m.left)
		m.right = optimizeMatcher(m.right)

		r, ok := m.value.(mText)
		if !ok {
			return m
		}
		leftNil := m.left == nil
		rightNil := m.right == nil
		if leftNil && rightNil {
			return newText(r.str)
		}

		_, leftSuper := m.left.(mSuper)
		lp, leftPrefix := m.left.(mPrefix)
		_, leftAny := m.left.(mAny)

		_, rightSuper := m.right.(mSuper)
		rs, rightSuffix := m.right.(mSuffix)
		_, rightAny := m.right.(mAny)

		switch {
		case leftSuper && rightSuper:
			return mContains{needle: r.str}
		case leftSuper && rightNil:
			return mSuffix{r.str}
		case rightSuper && leftNil:
			return mPrefix{r.str}
		case leftNil && rightAny:
			return mPrefixAny{prefix: r.str}
		case leftAny && rightNil:
			return mSuffixAny{suffix: r.str}
		case leftPrefix && rightSuffix:
			return mPrefixSuffix{lp.prefix, rs.suffix}
		case leftNil && rightSuffix:
			return mPrefixSuffix{r.str, rs.suffix}
		case rightNil && leftPrefix:
			return mPrefixSuffix{lp.prefix, r.str}
		}
		return m
	}
	return matcher
}

func compileMatchers(matchers []globMatcher) (globMatcher, error) {
	if len(matchers) == 0 {
		return nil, errors.New("compile error: need at least one matcher")
	}
	if len(matchers) == 1 {
		return matchers[0], nil
	}
	if m := glueMatchers(matchers); m != nil {
		return m, nil
	}

	idx := -1
	maxLen := -1
	var val globMatcher
	for i, matcher := range matchers {
		if l := matcher.Len(); l != -1 && l >= maxLen {
			maxLen = l
			idx = i
			val = matcher
		}
	}

	if val == nil {
		r, err := compileMatchers(matchers[1:])
		if err != nil {
			return nil, err
		}
		return newBTree(matchers[0], nil, r), nil
	}

	left := matchers[:idx]
	var right []globMatcher
	if len(matchers) > idx+1 {
		right = matchers[idx+1:]
	}

	var l, r globMatcher
	var err error
	if len(left) > 0 {
		l, err = compileMatchers(left)
		if err != nil {
			return nil, err
		}
	}
	if len(right) > 0 {
		r, err = compileMatchers(right)
		if err != nil {
			return nil, err
		}
	}
	return newBTree(val, l, r), nil
}

func glueMatchers(matchers []globMatcher) globMatcher {
	if m := glueMatchersAsEvery(matchers); m != nil {
		return m
	}
	if m := glueMatchersAsRow(matchers); m != nil {
		return m
	}
	return nil
}

func glueMatchersAsRow(matchers []globMatcher) globMatcher {
	if len(matchers) <= 1 {
		return nil
	}
	var (
		c []globMatcher
		l int
	)
	for _, matcher := range matchers {
		ml := matcher.Len()
		if ml == -1 {
			return nil
		}
		c = append(c, matcher)
		l += ml
	}
	return newRow(l, c...)
}

func runesEqual(a, b []rune) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func glueMatchersAsEvery(matchers []globMatcher) globMatcher {
	if len(matchers) <= 1 {
		return nil
	}
	var (
		hasAny    bool
		hasSuper  bool
		hasSingle bool
		min       int
		separator []rune
	)
	for i, matcher := range matchers {
		var sep []rune
		switch m := matcher.(type) {
		case mSuper:
			sep = []rune{}
			hasSuper = true
		case mAny:
			sep = m.seps
			hasAny = true
		case mSingle:
			sep = m.seps
			hasSingle = true
			min++
		case mList:
			if !m.not {
				return nil
			}
			sep = m.list
			hasSingle = true
			min++
		default:
			return nil
		}
		if i == 0 {
			separator = sep
		}
		if runesEqual(sep, separator) {
			continue
		}
		return nil
	}

	if hasSuper && !hasAny && !hasSingle {
		return mSuper{}
	}
	if hasAny && !hasSuper && !hasSingle {
		return mAny{seps: separator}
	}
	if (hasAny || hasSuper) && min > 0 && len(separator) == 0 {
		return mMin{min}
	}

	every := mEveryOf{}
	if min > 0 {
		every.ms = append(every.ms, mMin{min})
		if !hasAny && !hasSuper {
			every.ms = append(every.ms, mMax{min})
		}
	}
	if len(separator) > 0 {
		every.ms = append(every.ms, mContains{needle: string(separator), not: true})
	}
	return every
}

func minimizeMatchers(matchers []globMatcher) []globMatcher {
	var done globMatcher
	var left, right, count int

	for l := 0; l < len(matchers); l++ {
		for r := len(matchers); r > l; r-- {
			if glued := glueMatchers(matchers[l:r]); glued != nil {
				var swap bool
				if done == nil {
					swap = true
				} else {
					cl, gl := done.Len(), glued.Len()
					swap = cl > -1 && gl > -1 && gl > cl
					swap = swap || count < r-l
				}
				if swap {
					done = glued
					left = l
					right = r
					count = r - l
				}
			}
		}
	}

	if done == nil {
		return matchers
	}

	next := append(append([]globMatcher{}, matchers[:left]...), done)
	if right < len(matchers) {
		next = append(next, matchers[right:]...)
	}
	if len(next) == len(matchers) {
		return next
	}
	return minimizeMatchers(next)
}

// Matchers.

var segments0 = []int{0}
var segmentsByRuneLength = [5][]int{
	0: {0},
	1: {1},
	2: {2},
	3: {3},
	4: {4},
}

func indexAnyRunes(s string, rs []rune) int {
	for _, r := range rs {
		if i := strings.IndexRune(s, r); i != -1 {
			return i
		}
	}
	return -1
}

func indexRune(rs []rune, r rune) int {
	for i, c := range rs {
		if c == r {
			return i
		}
	}
	return -1
}

type mNothing struct{}

func (mNothing) Match(s string) bool         { return len(s) == 0 }
func (mNothing) Index(string) (int, []int) { return 0, segments0 }
func (mNothing) Len() int                  { return lenZero }

type mText struct {
	str         string
	runesLength int
	segments    []int
}

func newText(s string) mText {
	return mText{str: s, runesLength: utf8.RuneCountInString(s), segments: []int{len(s)}}
}

func (t mText) Match(s string) bool { return t.str == s }
func (t mText) Len() int            { return t.runesLength }
func (t mText) Index(s string) (int, []int) {
	index := strings.Index(s, t.str)
	if index == -1 {
		return -1, nil
	}
	return index, t.segments
}

type mAny struct{ seps []rune }

func (a mAny) Match(s string) bool { return indexAnyRunes(s, a.seps) == -1 }
func (a mAny) Len() int            { return lenNo }
func (a mAny) Index(s string) (int, []int) {
	found := indexAnyRunes(s, a.seps)
	switch found {
	case -1:
	case 0:
		return 0, segments0
	default:
		s = s[:found]
	}
	segments := make([]int, 0, len(s)+1)
	for i := range s {
		segments = append(segments, i)
	}
	segments = append(segments, len(s))
	return 0, segments
}

type mSuper struct{}

func (mSuper) Match(string) bool { return true }
func (mSuper) Len() int          { return lenNo }
func (mSuper) Index(s string) (int, []int) {
	segments := make([]int, 0, len(s)+1)
	for i := range s {
		segments = append(segments, i)
	}
	segments = append(segments, len(s))
	return 0, segments
}

type mSingle struct{ seps []rune }

func (m mSingle) Match(s string) bool {
	r, w := utf8.DecodeRuneInString(s)
	if len(s) > w {
		return false
	}
	return indexRune(m.seps, r) == -1
}
func (m mSingle) Len() int { return lenOne }
func (m mSingle) Index(s string) (int, []int) {
	for i, r := range s {
		if indexRune(m.seps, r) == -1 {
			return i, segmentsByRuneLength[utf8.RuneLen(r)]
		}
	}
	return -1, nil
}

type mList struct {
	list []rune
	not  bool
}

func (m mList) Match(s string) bool {
	r, w := utf8.DecodeRuneInString(s)
	if len(s) > w {
		return false
	}
	inList := indexRune(m.list, r) != -1
	return inList == !m.not
}
func (m mList) Len() int { return lenOne }
func (m mList) Index(s string) (int, []int) {
	for i, r := range s {
		if m.not == (indexRune(m.list, r) == -1) {
			return i, segmentsByRuneLength[utf8.RuneLen(r)]
		}
	}
	return -1, nil
}

type mRange struct {
	lo, hi rune
	not    bool
}

func (m mRange) Len() int { return lenOne }
func (m mRange) Match(s string) bool {
	r, w := utf8.DecodeRuneInString(s)
	if len(s) > w {
		return false
	}
	inRange := r >= m.lo && r <= m.hi
	return inRange == !m.not
}
func (m mRange) Index(s string) (int, []int) {
	for i, r := range s {
		if m.not != (r >= m.lo && r <= m.hi) {
			return i, segmentsByRuneLength[utf8.RuneLen(r)]
		}
	}
	return -1, nil
}

type mAnyOf struct{ ms []globMatcher }

func (a mAnyOf) Match(s string) bool {
	for _, m := range a.ms {
		if m.Match(s) {
			return true
		}
	}
	return false
}

func appendMerge(target, sub []int) []int {
	lt, ls := len(target), len(sub)
	out := make([]int, 0, lt+ls)
	for x, y := 0, 0; x < lt || y < ls; {
		if x >= lt {
			out = append(out, sub[y:]...)
			break
		}
		if y >= ls {
			out = append(out, target[x:]...)
			break
		}
		xValue := target[x]
		yValue := sub[y]
		switch {
		case xValue == yValue:
			out = append(out, xValue)
			x++
			y++
		case xValue < yValue:
			out = append(out, xValue)
			x++
		case yValue < xValue:
			out = append(out, yValue)
			y++
		}
	}
	return append(target[:0], out...)
}

func (a mAnyOf) Index(s string) (int, []int) {
	index := -1
	segments := make([]int, 0, len(s))
	for _, m := range a.ms {
		idx, seg := m.Index(s)
		if idx == -1 {
			continue
		}
		if index == -1 || idx < index {
			index = idx
			segments = append(segments[:0], seg...)
			continue
		}
		if idx > index {
			continue
		}
		segments = appendMerge(segments, seg)
	}
	if index == -1 {
		return -1, nil
	}
	return index, segments
}

func (a mAnyOf) Len() (l int) {
	l = -1
	for _, m := range a.ms {
		ml := m.Len()
		switch {
		case l == -1:
			l = ml
			continue
		case ml == -1:
			return -1
		case l != ml:
			return -1
		}
	}
	return
}

type mEveryOf struct{ ms []globMatcher }

func (e mEveryOf) Len() (l int) {
	for _, m := range e.ms {
		if ml := m.Len(); l > 0 {
			l += ml
		} else {
			return -1
		}
	}
	return
}

func (e mEveryOf) Index(s string) (int, []int) {
	var index int
	var offset int
	next := make([]int, 0, len(s))
	current := make([]int, 0, len(s))
	sub := s
	for i, m := range e.ms {
		idx, seg := m.Index(sub)
		if idx == -1 {
			return -1, nil
		}
		if i == 0 {
			current = append(current, seg...)
		} else {
			next = next[:0]
			delta := index - (idx + offset)
			for _, ex := range current {
				for _, n := range seg {
					if ex+delta == n {
						next = append(next, n)
					}
				}
			}
			if len(next) == 0 {
				return -1, nil
			}
			current = append(current[:0], next...)
		}
		index = idx + offset
		sub = s[index:]
		offset += idx
	}
	return index, current
}

func (e mEveryOf) Match(s string) bool {
	for _, m := range e.ms {
		if !m.Match(s) {
			return false
		}
	}
	return true
}

type mMin struct{ limit int }

func (m mMin) Match(s string) bool {
	var l int
	for range s {
		l++
		if l >= m.limit {
			return true
		}
	}
	return false
}
func (m mMin) Index(s string) (int, []int) {
	var count int
	c := len(s) - m.limit + 1
	if c <= 0 {
		return -1, nil
	}
	segments := make([]int, 0, c)
	for i, r := range s {
		count++
		if count >= m.limit {
			segments = append(segments, i+utf8.RuneLen(r))
		}
	}
	if len(segments) == 0 {
		return -1, nil
	}
	return 0, segments
}
func (m mMin) Len() int { return lenNo }

type mMax struct{ limit int }

func (m mMax) Match(s string) bool {
	var l int
	for range s {
		l++
		if l > m.limit {
			return false
		}
	}
	return true
}
func (m mMax) Index(s string) (int, []int) {
	segments := make([]int, 0, m.limit+1)
	segments = append(segments, 0)
	var count int
	for i, r := range s {
		count++
		if count > m.limit {
			break
		}
		segments = append(segments, i+utf8.RuneLen(r))
	}
	return 0, segments
}
func (m mMax) Len() int { return lenNo }

type mContains struct {
	needle string
	not    bool
}

func (c mContains) Match(s string) bool { return strings.Contains(s, c.needle) != c.not }
func (c mContains) Index(s string) (int, []int) {
	var offset int
