			return -1, nil
		}
		offset = idx + len(c.needle)
		if len(s) <= offset {
			return 0, []int{offset}
		}
		s = s[offset:]
	} else if idx != -1 {
		s = s[:idx]
	}
	segments := make([]int, 0, len(s)+1)
	for i := range s {
		segments = append(segments, offset+i)
	}
	return 0, append(segments, offset+len(s))
}
func (c mContains) Len() int { return lenNo }

type mPrefix struct{ prefix string }

func (p mPrefix) Index(s string) (int, []int) {
	idx := strings.Index(s, p.prefix)
	if idx == -1 {
		return -1, nil
	}
	length := len(p.prefix)
	var sub string
	if len(s) > idx+length {
		sub = s[idx+length:]
	} else {
		sub = ""
	}
	segments := make([]int, 0, len(sub)+1)
	segments = append(segments, length)
	for i, r := range sub {
		segments = append(segments, length+i+utf8.RuneLen(r))
	}
