}
func (p mPrefix) Len() int            { return lenNo }
func (p mPrefix) Match(s string) bool { return strings.HasPrefix(s, p.prefix) }

type mSuffix struct{ suffix string }

func (p mSuffix) Len() int            { return lenNo }
func (p mSuffix) Match(s string) bool { return strings.HasSuffix(s, p.suffix) }
func (p mSuffix) Index(s string) (int, []int) {
	idx := strings.Index(s, p.suffix)
	if idx == -1 {
		return -1, nil
	}
	return 0, []int{idx + len(p.suffix)}
}

type mPrefixAny struct {
	prefix string
	seps   []rune
}

func (p mPrefixAny) Index(s string) (int, []int) {
	idx := strings.Index(s, p.prefix)
	if idx == -1 {
		return -1, nil
	}
	n := len(p.prefix)
	sub := s[idx+n:]
	if i := indexAnyRunes(sub, p.seps); i > -1 {
		sub = sub[:i]
	}
	seg := make([]int, 0, len(sub)+1)
	seg = append(seg, n)
	for i, r := range sub {
		seg = append(seg, n+i+utf8.RuneLen(r))
	}
	return idx, seg
}
func (p mPrefixAny) Len() int { return lenNo }
func (p mPrefixAny) Match(s string) bool {
	if !strings.HasPrefix(s, p.prefix) {
		return false
	}
	return indexAnyRunes(s[len(p.prefix):], p.seps) == -1
}

type mSuffixAny struct {
	suffix string
	seps   []rune
}

func (p mSuffixAny) Index(s string) (int, []int) {
	idx := strings.Index(s, p.suffix)
	if idx == -1 {
		return -1, nil
	}
	i := lastIndexAnyRunes(s[:idx], p.seps) + 1
	return i, []int{idx + len(p.suffix) - i}
}
func (p mSuffixAny) Len() int { return lenNo }
func (p mSuffixAny) Match(s string) bool {
	if !strings.HasSuffix(s, p.suffix) {
		return false
	}
	return indexAnyRunes(s[:len(s)-len(p.suffix)], p.seps) == -1
}

func lastIndexAnyRunes(s string, rs []rune) int {
	for _, r := range rs {
		i := -1
		if 0 <= r && r < utf8.RuneSelf {
			i = strings.LastIndexByte(s, byte(r))
		} else {
			sub := s
			for len(sub) > 0 {
				j := strings.IndexRune(s, r)
				if j == -1 {
					break
				}
				i = j
				sub = sub[i+1:]
			}
		}
		if i != -1 {
			return i
		}
	}
	return -1
}

type mPrefixSuffix struct{ prefix, suffix string }

func (p mPrefixSuffix) Index(s string) (int, []int) {
	prefixIdx := strings.Index(s, p.prefix)
	if prefixIdx == -1 {
		return -1, nil
	}
	suffixLen := len(p.suffix)
	if suffixLen <= 0 {
		return prefixIdx, []int{len(s) - prefixIdx}
	}
	if (len(s) - prefixIdx) <= 0 {
		return -1, nil
	}
	segments := make([]int, 0, len(s)-prefixIdx)
	for sub := s[prefixIdx:]; ; {
		suffixIdx := strings.LastIndex(sub, p.suffix)
		if suffixIdx == -1 {
			break
		}
		segments = append(segments, suffixIdx+suffixLen)
		sub = sub[:suffixIdx]
	}
	if len(segments) == 0 {
		return -1, nil
	}
	for i, j := 0, len(segments)-1; i < j; i, j = i+1, j-1 {
		segments[i], segments[j] = segments[j], segments[i]
	}
	return prefixIdx, segments
}
func (p mPrefixSuffix) Len() int { return lenNo }
func (p mPrefixSuffix) Match(s string) bool {
	return strings.HasPrefix(s, p.prefix) && strings.HasSuffix(s, p.suffix)
}

type mRow struct {
	ms          []globMatcher
	runesLength int
	segments    []int
}

func newRow(l int, m ...globMatcher) mRow {
	return mRow{ms: m, runesLength: l, segments: []int{l}}
}

func (r mRow) matchAll(s string) bool {
	var idx int
	for _, m := range r.ms {
		length := m.Len()
		var next, i int
		for next = range s[idx:] {
			i++
			if i == length {
				break
			}
		}
		if i < length || !m.Match(s[idx:idx+next+1]) {
			return false
		}
		idx += next + 1
	}
	return true
}

func (r mRow) lenOk(s string) bool {
	var i int
	for range s {
		i++
		if i > r.runesLength {
			return false
		}
	}
	return r.runesLength == i
}

func (r mRow) Match(s string) bool { return r.lenOk(s) && r.matchAll(s) }
func (r mRow) Len() int            { return r.runesLength }
func (r mRow) Index(s string) (int, []int) {
	for i := range s {
		if len(s[i:]) < r.runesLength {
			break
		}
		if r.matchAll(s[i:]) {
			return i, r.segments
		}
	}
	return -1, nil
}

type mBTree struct {
	value, left, right globMatcher

	valueLengthRunes int
	leftLengthRunes  int
	rightLengthRunes int
	lengthRunes      int
}

func newBTree(value, left, right globMatcher) mBTree {
	t := mBTree{value: value, left: left, right: right}
	lenOk := true
	if t.valueLengthRunes = value.Len(); t.valueLengthRunes == -1 {
		lenOk = false
	}
	if left != nil {
		if t.leftLengthRunes = left.Len(); t.leftLengthRunes == -1 {
			lenOk = false
		}
	}
	if right != nil {
		if t.rightLengthRunes = right.Len(); t.rightLengthRunes == -1 {
			lenOk = false
		}
	}
	if lenOk {
		t.lengthRunes = t.leftLengthRunes + t.valueLengthRunes + t.rightLengthRunes
	} else {
		t.lengthRunes = -1
	}
	return t
}

func (t mBTree) Len() int                  { return t.lengthRunes }
func (t mBTree) Index(string) (int, []int) { return -1, nil }

func (t mBTree) Match(s string) bool {
	inputLen := len(s)
	if t.lengthRunes != -1 && t.lengthRunes > inputLen {
		return false
	}

	var offset, limit int
	if t.leftLengthRunes >= 0 {
		offset = t.leftLengthRunes
	}
	if t.rightLengthRunes >= 0 {
		limit = inputLen - t.rightLengthRunes
	} else {
		limit = inputLen
	}

	for offset < limit {
		index, segments := t.value.Index(s[offset:limit])
		if index == -1 {
			return false
		}

		l := s[:offset+index]
		var left bool
		if t.left != nil {
			left = t.left.Match(l)
		} else {
			left = l == ""
		}

		if left {
			for i := len(segments) - 1; i >= 0; i-- {
				length := segments[i]
				var right bool
				var r string
				if inputLen <= offset+index+length {
					r = ""
				} else {
					r = s[offset+index+length:]
				}
				if t.right != nil {
					right = t.right.Match(r)
				} else {
					right = r == ""
				}
				if right {
					return true
				}
			}
		}

		_, step := utf8.DecodeRuneInString(s[offset+index:])
		offset += index + step
	}
	return false
}
